 "زر واتساب مقابل محادثة واتساب للأعمال": "WhatsApp button vs WhatsApp Business chat",
 "زر واتساب يفتح تطبيق واتساب لدى الزائر برسالة مكتوبة مسبقاً إلى رقمك (wa.me) — لا يحتاج API، والمحادثة تتم في واتساب. أما «واتساب للأعمال (API)» فيجعل الرسائل تصل إلى صندوق وارد الدعم هنا ويرد عليها الفريق بتتبع حالة التسليم. إذا كان رقم الزر هو نفس رقم الـAPI المتصل، تظهر المحادثات في صندوق الوارد تلقائياً.": "The WhatsApp button opens the visitor's WhatsApp with a prefilled message to your number (wa.me) — no API needed, and the chat happens in WhatsApp. “WhatsApp Business (API)” brings messages into the support inbox here, where the team replies with delivery tracking. If the button's number is the connected API number, those chats appear in the inbox automatically.",
