 "سياسة إكمال المشروع": "Project completion policy",
 "سيتم إبلاغ الموظف بسبب الرفض ليعيد الرفع.": "The employee will be told the rejection reason so they can re-upload.",
 "سيتم إخفاء العميل المحتمل من القوائم مع الاحتفاظ بكل سجلاته. يمكن استعادته لاحقاً.": "The lead will be hidden from lists while keeping all its records. It can be restored later.",
 "سيتم إنشاء المشروع وجدول الدفعات والفاتورة الأولى والعمولة وبدء تهيئة العميل تلقائياً. العملية لا تنشئ سجلات مكررة.": "The project, payment schedule, first invoice and commission will be created and client onboarding started automatically. It doesn't create duplicate records.",
 "سيتم إنشاء جدول الدفعات والفاتورة الأولى والعمولة وبدء تهيئة العميل تلقائياً. العملية لا تنشئ سجلات مكررة.": "The payment schedule, first invoice and commission are created and client onboarding starts automatically. No duplicate records are created.",
 "سيتم إنشاء حساب بوابة لجهة الاتصال وإرسال رابط تعيين كلمة المرور إلى بريدها.": "A portal account will be created for the contact and a set-password link sent to their email.",
 "سيتم إنشاء قائمة إنهاء الخدمة (سحب الحسابات والصلاحيات، استرجاع الأجهزة والأصول، التسوية المالية، مقابلة الخروج، الموافقة النهائية).": "An offboarding checklist will be created (revoke accounts and access, return devices and assets, financial settlement, exit interview, final approval).",
 "سيتم إنشاء مراجعة (مسودة) لكل موظف نشط، والمراجِع هو المدير المباشر.": "A review (draft) will be created for each active employee, with their direct manager as the reviewer.",
 "سيتم إنشاء/تحديث السجلات الآن. متابعة؟": "Records will be created/updated now. Continue?",
 "سيتم إنهاء جلسات الموظف ومنع دخوله للنظام.": "The employee's sessions will be ended and their sign-in blocked.",
 "سيتم تحديث ميزانية المشروع وموعده النهائي ونطاقه، وإنشاء فاتورة مسودة للتكلفة الإضافية.": "The project budget, deadline and scope will be updated, and a draft invoice created for the additional cost.",
 "سيتم ترحيل تكلفة كل راتب إلى المصروفات في المالية، وتسوية العمل الإضافي والمكافآت والعمولات وأقساط القروض والمصروفات المستردة.": "Each salary's cost will be posted to Finance expenses, and overtime, bonuses, commissions, loan instalments and reimbursed expenses settled.",
 "سيتم رفض الطلب مع حفظ السبب في السجل.": "The request will be rejected and the reason kept in the record.",
 "سيتم كتابة {n} سجل.": "{n} records will be written.",
 "سيتم نشر الصورة الأولى فقط.": "Only the first image will be published.",
 "سيتم نقل كل جهات الاتصال والصفقات والمشاريع والعقود والفواتير والدفعات والتذاكر والملفات والسجل الزمني إلى الحساب الهدف، ثم أرشفة هذا الحساب. العملية مسجلة في سجل التدقيق ولا يمكن التراجع عنها تلقائياً.": "All contacts, deals, projects, contracts, invoices, payments, tickets, files and the timeline will move to the target account, and this account will then be archived. The operation is recorded in the audit log and can't be undone automatically.",
 "سيقوم النظام تلقائياً وفي عملية واحدة بـ:": "In one operation, the system will automatically:",
 "سيُحذف الحساب وبيانات اعتماده المشفّرة نهائياً. السجلات السابقة تبقى.": "The account and its encrypted credentials will be deleted permanently. Past logs stay.",
 "سيُحذف حساب الدخول غير المستخدم لـ {email} ويبقى ملف الموظف. يمكن إنشاء دعوة جديدة لاحقاً.": "The unused sign-in account for {email} will be deleted and the employee file kept. A new invitation can be created later.",
 "سيُحذف ما أُنشئ ويُستعاد ما عُدّل. متابعة؟": "Created records will be removed and changed ones restored. Continue?",
 "سيُرسل رابط آمن إلى بريد المستخدم لتعيين كلمة مرور جديدة. لا يرى أحد كلمة المرور.": "A secure link will be sent to the user's email to set a new password. Nobody sees the password.",
 "سيُنشأ إصدار جديد بمحتوى الإصدار v{v}. السجل السابق يبقى كما هو.": "A new version will be created with the content of v{v}. Earlier history stays as it is.",
 "سيُنشئ النظام مهمة متابعة تلقائياً": "The system will create a follow-up task automatically",
 "سيُنشر على كل المنصات المختارة الآن. متابعة؟": "This will publish to every selected platform now. Continue?",
