 "يبدأ إنهاء الخدمة من صفحة الموظف (استقالة / إنهاء خدمة).": "Offboarding starts from the employee page (resignation / termination).",
 "يبدو أن الملاحظات تحتوي كلمة مرور أو سراً. لا تحفظ كلمات المرور في النظام — استخدم مدير كلمات المرور.": "The notes seem to contain a password or secret. Don't keep passwords in the system — use the password manager.",
 "يبقى المستند في السجل كمؤرشف.": "The document stays in the record as archived.",
 "يبقى المستند في السجل كملغى ولا يمكن تعديله.": "The document stays in the record as void and can't be edited.",
 "يتجاوز 100%": "Exceeds 100%",
