 "يتطلب 2FA": "Requires 2FA",
 "يتطلب استرداد": "Requires return",
 "يتطلب اكتمال قائمة إنهاء الخدمة (بما فيها الموافقة النهائية) واسترجاع الأجهزة وسحب الصلاحيات. يُحظر الدخول وتُنهى العقود السارية مع الاحتفاظ بكل السجلات.": "Requires the offboarding checklist (including final approval) to be complete, devices returned and access revoked. Sign-in is blocked and active contracts are ended, while all records are kept.",
 "يتطلب المقترح موافقة المراجعة الداخلية قبل الإرسال (Settings → Approval policies).": "The proposal needs internal review approval before sending (Settings → Approval policies).",
 "يتطلب صلاحية بيانات الموظفين الحساسة.": "Requires access to sensitive employee data.",
 "يتطلب مرفقاً": "Requires an attachment",
 "يتم الحساب تلقائياً: الأساسي والبدلات، الغياب والإجازات بدون أجر والتأخير، العمل الإضافي المعتمد، المكافآت والعمولات المعتمدة، أقساط القروض والسلف، المصروفات المستردة، التأمينات والضرائب.": "Calculated automatically: basic and allowances, absence, unpaid leave and lateness, approved overtime, approved bonuses and commissions, loan and advance instalments, reimbursed expenses, social insurance and taxes.",
 "يتم الرفع من تبويب «الملفات» داخل كل مشروع": "Upload from the “Files” tab inside each project",
 "يتم عرض أحدث السجلات فقط؛ استخدم الفلاتر لتضييق النتائج.": "Only the latest records are shown; use filters to narrow the results.",
 "يجب أن يحتوي JSON على مصفوفة من السجلات.": "The JSON must contain an array of records.",
