 "يجب ربط النشاط بسجل (عميل محتمل، صفقة، حساب، جهة اتصال أو مشروع).": "The activity must be linked to a record (lead, deal, account, contact or project).",
 "يجب وجود مرحلة «خاسرة» واحدة بالضبط.": "There must be exactly one “Lost” stage.",
 "يجب وجود مرحلة «مكسوبة» واحدة بالضبط.": "There must be exactly one “Won” stage.",
